<?php
require __DIR__.'/../includes/bootstrap.php';require_role('admin');$error=null;$draft=null;
if(is_post()){
 verify_csrf();try{
  if(input('action')==='features'){check_edit_version('features',0);
   $selections=[];foreach(['featured_book','featured_audio'] as $key){$id=input_int($key);if($id&&!find_book($id))throw new DomainException('Choose an existing book.');$selections[$key]=$id;}transaction(function()use($selections){foreach($selections as $key=>$id)reading_upsert('app_settings',['setting_key'=>$key],['setting_value'=>(string)$id]);});
   log_activity('content.featured','Updated dashboard selections');flash('success','Featured books saved.');
  }elseif(input('action')==='collection'){
   $name=input('title');$subtitle=input('subtitle');$id=input_int('collection_id');
   $draft=['id'=>$id,'title'=>$name,'subtitle'=>$subtitle,'sort_order'=>input_int('sort_order'),'is_active'=>input('is_active')==='1'?1:0];
   if($name===''||mb_strlen($name)>160||mb_strlen($subtitle)>240)throw new DomainException('Use a collection title of 1–160 characters and a subtitle of up to 240 characters.');
   if($id)check_edit_version('collection',$id);if($id&&!q_val('SELECT id FROM collections WHERE id=?',[$id]))throw new DomainException('Collection not found.');
   if(input_int('sort_order')<0||input_int('sort_order')>9999)throw new DomainException('Display order must be between 0 and 9999.');
   $raw=$_POST['books']??[];if(!is_array($raw)||count($raw)>500)throw new DomainException('Choose at most 500 books.');foreach($raw as $value)if(!is_scalar($value))throw new DomainException('Invalid book selection.');
   $ids=array_values(array_unique(array_map('intval',$raw)));foreach($ids as $bid)if(!find_book($bid))throw new DomainException('A selected book no longer exists.');
   $positions=$_POST['book_positions']??[];if(!is_array($positions))throw new DomainException('Invalid book order.');
   $ranks=[];foreach($ids as $index=>$bid){$rank=$positions[$bid]??($index+1);if(!is_scalar($rank)||!ctype_digit((string)$rank)||(int)$rank>9999)throw new DomainException('Book order must use whole numbers from 0 to 9999.');$ranks[$bid]=(int)$rank;}
   usort($ids,fn($a,$b)=>$ranks[$a]<=>$ranks[$b]);
   transaction(function()use(&$id,$name,$subtitle,$ids){if($id)q('UPDATE collections SET title=?,subtitle=?,sort_order=?,is_active=? WHERE id=?',[$name,$subtitle,input_int('sort_order'),input('is_active')==='1'?1:0,$id]);else{q('INSERT INTO collections (title,subtitle,sort_order,is_active) VALUES (?,?,?,?)',[$name,$subtitle,input_int('sort_order'),input('is_active')==='1'?1:0]);$id=(int)db()->lastInsertId();}q('DELETE FROM collection_books WHERE collection_id=?',[$id]);foreach($ids as $pos=>$bid)q('INSERT INTO collection_books (collection_id,book_id,position) VALUES (?,?,?)',[$id,$bid,$pos]);});
   log_activity('collection.saved',$name);flash('success','Collection saved.');
  }elseif(input('action')==='archive') {q('UPDATE collections SET is_active=0 WHERE id=?',[input_int('collection_id')]);flash('success','Collection hidden. You can publish it again from Edit.');}
  else throw new DomainException('Choose a valid content action.');
  redirect('admin/content.php');
 }catch(DomainException $e){$error=$e->getMessage();}
}
$books=q_all('SELECT id,title,author,pdf FROM books ORDER BY title');$collections=q_all('SELECT c.*, (SELECT COUNT(*) FROM collection_books cb WHERE cb.collection_id=c.id) AS book_count FROM collections c ORDER BY sort_order,id');
$edit=input_int('edit') ? q_one('SELECT * FROM collections WHERE id=?',[input_int('edit')]) : null;
$selected=$edit?array_map('intval',array_column(q_all('SELECT book_id FROM collection_books WHERE collection_id=? ORDER BY position',[$edit['id']]),'book_id')):[];
if($draft){$edit=$draft;$selected=array_values(array_unique(array_map('intval',array_filter((array)($_POST['books']??[]),'is_scalar'))));}
$collectionBooks=$books;$existingOrder=array_flip($selected);usort($collectionBooks,fn($a,$b)=>($existingOrder[(int)$a['id']]??PHP_INT_MAX)<=>($existingOrder[(int)$b['id']]??PHP_INT_MAX));
$title='Content & audio';$active='content';require __DIR__.'/../includes/partials/header.php';
?>
<header class="page-head"><div class="page-head__title"><h1>Content & audio</h1><p>Choose the books readers see, curate collections, and add recordings and chapters.</p></div><a class="btn btn--outline" href="<?= e(url('admin/backups.php')) ?>">Backups</a></header>
<?php if($error): ?><div class="alert alert--error" role="alert"><?= e($error) ?></div><?php endif; ?>
<div class="enhancement-grid"><section class="card stack"><h2>Dashboard selections</h2><form method="post" class="enhancement-form"><?= csrf_field() ?><input type="hidden" name="action" value="features"><input type="hidden" name="version" value="<?= e(edit_version('features',0)) ?>">
<?php foreach(['featured_book'=>'Featured reading','featured_audio'=>'Featured audio'] as $key=>$label): ?><div class="field"><label for="<?= $key ?>"><?= $label ?></label><select class="select" id="<?= $key ?>" name="<?= $key ?>"><option value="0">Automatic selection</option><?php foreach($books as $b): ?><option value="<?= (int)$b['id'] ?>" <?= (int)library_setting($key)===(int)$b['id']?'selected':'' ?>><?= e($b['title']) ?></option><?php endforeach; ?></select></div><?php endforeach; ?><p class="hint">A member's unfinished book takes priority for “Continue reading”. Audio titles without a recording use the labelled catalogue preview.</p><button class="btn" type="submit">Save featured books</button></form></section>
<section class="card stack"><h2><?= !empty($edit['id'])?'Edit collection':'Create a collection' ?></h2><form method="post" class="enhancement-form"><?= csrf_field() ?><input type="hidden" name="action" value="collection"><input type="hidden" name="collection_id" value="<?= (int)($edit['id']??0) ?>"><input type="hidden" name="version" value="<?= e(input('version',edit_version('collection',(int)($edit['id']??0)))) ?>">
<div class="field"><label for="collection-title">Title</label><input class="input" id="collection-title" name="title" maxlength="160" required value="<?= e($edit['title']??'') ?>"></div><div class="field"><label for="collection-subtitle">Subtitle</label><input class="input" id="collection-subtitle" name="subtitle" maxlength="240" value="<?= e($edit['subtitle']??'') ?>"></div>
<div class="field"><label for="collection-order">Display order</label><input class="input" type="number" id="collection-order" name="sort_order" min="0" max="9999" value="<?= (int)($edit['sort_order']??0) ?>"><span class="hint">The first published collection appears on the dashboard.</span></div><label><input type="checkbox" name="is_active" value="1" <?= $edit===null||$edit['is_active']?'checked':'' ?>> Published</label>
<fieldset><legend>Books in this collection</legend><p class="hint" id="collection-book-order-hint">Lower book-order numbers appear first. Existing order is kept when you edit a collection.</p><div class="collection-picker" data-collection-picker><?php foreach($collectionBooks as $index=>$b): $bid=(int)$b['id'];$checked=in_array($bid,$selected,true);$postedRank=$_POST['book_positions'][$bid]??null;$rank=is_scalar($postedRank)?(string)$postedRank:(string)(($existingOrder[$bid]??$index)+1); ?><div class="collection-choice"><label><input type="checkbox" name="books[]" value="<?= $bid ?>" <?= $checked?'checked':'' ?>><?= e($b['title']) ?></label><label class="collection-book-order"><span class="sr-only">Book order for <?= e($b['title']) ?></span><input class="input" type="number" min="0" max="9999" name="book_positions[<?= $bid ?>]" value="<?= e($rank) ?>" aria-describedby="collection-book-order-hint" <?= !$checked?'disabled':'' ?>></label></div><?php endforeach; ?></div></fieldset><button class="btn" type="submit">Save collection</button></form></section></div>
<section class="card stack"><h2>Your collections</h2><?php if(!$collections): ?><p class="muted">No curated collections yet. The dashboard continues to show new arrivals.</p><?php endif; ?><?php foreach($collections as $c): ?><div class="row row--wrap"><strong><?= e($c['title']) ?></strong><span class="muted"><?= (int)$c['book_count'] ?> books · <?= $c['is_active']?'Published':'Hidden' ?></span><a class="btn btn--ghost" href="<?= e(url('admin/content.php',['edit'=>$c['id']])) ?>">Edit</a><?php if($c['is_active']): ?><a class="btn btn--ghost" href="<?= e(url('collection.php',['id'=>$c['id']])) ?>">View</a><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="archive"><input type="hidden" name="version" value="<?= e(edit_version('collection',(int)$c['id'])) ?>"><input type="hidden" name="collection_id" value="<?= (int)$c['id'] ?>"><button class="btn btn--ghost" type="submit">Hide</button></form><?php endif; ?></div><?php endforeach; ?></section>
<section class="card stack"><h2>Recordings and chapter navigation</h2><p class="muted">Choose a title to upload audio and edit chapter markers for its recording or PDF.</p><ul class="content-book-list"><?php foreach($books as $b): ?><li><a href="<?= e(url('admin/media.php',['id'=>$b['id']])) ?>"><?= e($b['title']) ?><span><?= e($b['author']) ?></span></a></li><?php endforeach; ?></ul></section>
<script src="<?= e(asset('js/collection-editor.js')) ?>" defer></script>
